from pathlib import Path
p=Path('api/wms_api_server/app/modules/transport/infrastructure/available_sts_page.py');s=p.read_text(encoding='utf-8');s=s.replace('"group by P.ST_NUMBER,P.ADDR,P.WARE_ID "\n             "order by MIN(A.ORD) NULLS LAST,MIN(NVL(A.REGION,P.ADDR)),P.ST_NUMBER,P.WARE_ID,P.ADDR")','"group by P.ST_NUMBER,P.ADDR,P.WARE_ID")\n    headers=("select H.ST_NUMBER,H.ADDR,H.WARE_ID from ("+headers+") H "\n             "left join RABAEV.RRL_ADDR PAGE_ADDR on PAGE_ADDR.ADDR=H.ADDR "\n             "order by PAGE_ADDR.ORD NULLS LAST,NVL(PAGE_ADDR.REGION,H.ADDR),H.ST_NUMBER,H.WARE_ID,H.ADDR")');p.write_text(s,encoding='utf-8')
